176	          }
177	          value = value >> 1;
178	        }
179	      }
180	      context_enlargeIn--;
181	      if (context_enlargeIn == 0) {
182	        context_enlargeIn = Math.pow(2, context_numBits);
183	        context_numBits++;
184	      }
185	    }
186	    value = 2;
187	    for (i = 0; i < context_numBits; i++) {
188	      context_data_val = context_data_val << 1 | value & 1;
189	      if (context_data_position == bitsPerChar - 1) {
190	        context_data_position = 0;
191	        context_data.push(getCharFromInt(context_data_val));
192	        context_data_val = 0;
193	      } else {
194	        context_data_position++;
195	      }
196	      value = value >> 1;
197	    }
198	    while (true) {
199	      context_data_val = context_data_val << 1;
200	      if (context_data_position == bitsPerChar - 1) {
201	        context_data.push(getCharFromInt(context_data_val));
202	        break;
203	      } else context_data_position++;
204	    }
205	    return context_data.join("");
206	  }
207	  function buildHref(ex) {
208	    const documentText = ex.state === undefined ? "" : typeof ex.state === "string" ? ex.state : JSON.stringify(ex.state, null, 2);
209	    return "https://console.typesafe.ai/decode#share/" + compressToEncodedURIComponent(JSON.stringify({
210	      apiVersion: "v1",
211	      documentText,
212	      promptsText: JSON.stringify(ex.questions, null, 2),
213	      selectedModels: ex.selectedModels
214	    }));
215	  }
216	  const displayedExample = display === "questions" ? example.questions : example.state === undefined ? {
217	    questions: example.questions
218	  } : {
219	    state: example.state,
220	    questions: example.questions
221	  };
222	  const code = JSON.stringify(displayedExample, null, 2);
223	  const href = buildHref(example);
224	  return <div style={{
225	    margin: "1.25rem 0"
226	  }}>
227	      <CodeBlock language="json" filename={title ?? "request"}>
228	        {code}
229	      </CodeBlock>
230	      <div className="pb-8">
231	        <a href={href} target="_blank" rel="noreferrer" className="text-primary">
232	          Try it in the Playground →
233	        </a>
234	      </div>
235	    </div>;
236	}
237	
238	Use a Score when the answer is a position on a spectrum you can describe in steps. For example, how severe a bug is, how happy a customer is, or how much Python experience a candidate has. If the answer is one of a fixed set of options with no order between them, use a [Choice](/primitives/choice). If it's a yes or no, use a [Noul](/primitives/noul). [Choose a question type](/primitives#choose-a-question-type) compares all three.
239	
240	A Score answer is a position along your levels in `score`, which can fall between two levels. The model also returns a probability for every level in `probabilities`, and a `confidence` value for the answer.
241	
242	Example Score questions:
243	
244	```
245	"How severe is the bug being reported?"
246	  → 0: Cosmetic; no impact to functionality
247	  → 1: Broken or degraded feature, but workaround exists
248	  → 2: Blocking issue; no workaround exists
249	
250	"How formal is this outfit based on the description"
251	  → 0: gym clothes
252	  → 1: casual
253	  → 2: business casual
254	  → 3: formal
255	  → 4: black tie
256	
257	"How relevant is this candidate's experience to the job posting"
258	  → 0: completely unrelated
259	  → 1: adjacent field
260	  → 2: some direct experience
261	  → 3: deep, direct experience
262	```
263	
264	The numbers in front of each step are positions, explained under [Levels](#levels).
265	
266	## Request structure
267	
268	The POST request body to the [TypeSafe API](/api) has the same three top-level fields as any other question type: `state`, which is the content to evaluate; `model`; and `questions`. Each Score question has the following fields:
269	
270	* `type`: Always `"score"`.
271	* `instructions`: The question the model answers. What it's rating.
272	* `criteria`: An ordered array of level descriptions, from the low end of the scale to the high end. Needs at least two levels and takes up to 10.
273	
274	Below is a request where the state is a bug report and the question is how severe the bug is:
275	
276	<TypesafeExample
277	  display="request"
278	  example={{
279	state: 'The export button crashes the settings page in Safari. It works in Chrome, but a few of our customers only use Safari.',
280	selectedModels: ['jev-latest'],
281	questions: {
282	  bug_severity: {
283	    type: 'score',
284	    instructions: 'How severe is the reported issue?',
285	    criteria: [
286	      'Cosmetic; no impact to functionality',
287	      'Broken or degraded feature, but workaround exists',
288	      'Blocking issue; no workaround exists',
289	    ],
290	  },
291	},
292	}}
293	/>
294	
295	You choose the question id, `bug_severity` in this case. This id is not sent to the model. The answer is returned under the same id.
296	
297	### Levels
298	
299	Each entry in `criteria` is a level: one point on the spectrum of possible answers, described in words. A level's number is its position in the `criteria` array, starting at 0, so the three entries above are levels 0, 1 and 2. The order of the array is the numbering.
300	
301	The model gets the descriptions and nothing else, and each level is judged on its own against the state.
302	
303	The `score` in the response is a position on the levels spectrum. For a three-level scale it runs from 0 to 2, and it can land between two levels.
304	
305	Our [client SDKs](/sdk) provide typed questions. In Python, the same question is a `Score`:
306	
307	```python theme={null}
308	from typesafe_sdk import Score, TypeSafeClient
309	
310	with TypeSafeClient() as client:
311	    response = client.system_one(
312	        state="The export button crashes the settings page in Safari. It works in Chrome, but a few of our customers only use Safari.",
313	        questions={
314	            "bug_severity": Score(
315	                instructions="How severe is the reported issue?",
316	                criteria=[
317	                    "Cosmetic; no impact to functionality",
318	                    "Broken or degraded feature, but workaround exists",
319	                    "Blocking issue; no workaround exists",
320	                ],
321	            ),
322	        },
323	    )
324	
325	    print(response.answers["bug_severity"].score)
326	```
327	
328	Use the `system_one` method or the `https://api.typesafe.ai/v1/systemone` endpoint to call a System One model. The `model` field selects which model handles the request. [How to build with TypeSafe](/concepts/how-to-build-with-system-one) covers where in your code to call it.
329	
330	Use one of our [client SDKs](/sdk) or call the [TypeSafe API](/api) directly. If a coding agent is writing the integration for you, install the [TypeSafe agent skill](/agent-skill#installation) first so it knows the request and response shapes.
331	
332	<Note>
333	  `instructions` and each level in `criteria` can be a string, an object, or an array. Start with strings. Use an object when a level needs a description plus a few example situations. See [Structured level descriptions](#structured-level-descriptions) below and the [API reference](/api#param-instructions-2).
334	</Note>
335	
336	## Response structure
337	
338	The response has one entry in `answers` per question, under the ids from the request. This is the response to the example request above:
339	
340	```json theme={null}
341	{
342	  "model": "jev-latest",
343	  "answers": {
344	    "bug_severity": {
345	      "type": "score",
346	      "score": 1.3,
347	      "confidence": 0.54,
348	      "legend": {
349	        "0": "Cosmetic; no impact to functionality",
350	        "1": "Broken or degraded feature, but workaround exists",
351	        "2": "Blocking issue; no workaround exists"
352	      },
353	      "probabilities": {
354	        "0": 0.0,
355	        "1": 0.7,
356	        "2": 0.3
357	      }
358	    }
359	  },
360	  "usage": {
361	    "input_tokens": 332,
362	    "output_tokens": 18
363	  }
364	}
365	```
366	
367	Each Score answer has five values:
368	
369	* `type`: The type of TypeSafe question.
370	* `probabilities`: The probability of each level, keyed by level number as a string. The sum of all values is 1.
371	* `score`: The position on the level number line, from 0 to the top level number, which is 2 here. It's each level number multiplied by its probability, added up: 0 x 0.0 + 1 x 0.70 + 2 x 0.30 = 1.30.
372	* `legend`: Each level number mapped back to its description.
373	* [`confidence`](/confidence): A number from 0 to 1 computed from how `probabilities` is spread. A single peak on one level means high confidence. Probability spread over several levels means low confidence.
374	
375	A score of 1.30 means mostly level 1 with some weight on level 2. That matches the report: the export is broken, and switching to Chrome is a workaround for most customers, but not for the ones who only use Safari. The model puts 0.70 on "workaround exists" and 0.30 on "no workaround", and confidence is 0.54 because it's split.
376	
377	Using the Python SDK, `ScoreAnswer` has `score`, `confidence`, `probabilities`, and `legend` as typed fields. The SDK keys `probabilities` and `legend` by integer level rather than by string.
378	
